"""R15: leer, planificar y resolver problemas de medidas y perímetros."""
import json
from decimal import Decimal as D
from pathlib import Path
U=[]
def f(x):
 s=format(D(x),'f');return (s.rstrip('0').rstrip('.') if '.' in s else s).replace('.',',')
def datos(*lines):return dict(tipo='datos',lineas=list(lines))
def rectangle(m,cm,note,altura_m=False):return dict(tipo='poligono',puntos=[[0,0],[float(D(m)),0],[float(D(m)),cm/100],[0,cm/100]],lados=[f(m)+' m',(f(D(cm)/100)+' m' if altura_m else str(cm)+' cm'),'',''],nota=note)
def act(q,value,solution,wrong,visual):
 options=list(dict.fromkeys(map(str,[value,*wrong])));assert len(options)>=2
 return dict(enunciado=q,respuesta_correcta=str(value),opciones=options,paso_resuelto=solution,visual=visual)
def unit(id,t,after,title,exp,example,steps,hint,rows,visual):
 assert len(rows)==6
 for i,r in enumerate(rows):
  r['id']=id+'-v'+str(i+1);k=i%len(r['opciones']);r['opciones']=r['opciones'][k:]+r['opciones'][:k]
 U.append(dict(id=id,tema=t,despues_de=after,titulo=title,explicacion=exp,ejemplo=example,pasos=steps,pista=hint,actividades=rows,visual=visual))
cuts=[('2',3,25,40),('1.5',2,30,50),('3',4,40,60),('2.5',3,50,30),('1.2',4,20,70),('4',5,60,80)]
t='si_me_la_longitud'
unit('prof_prob_datos',t,'prof_med_long_problema','Leer qué nos piden y elegir los datos','Antes de calcular, leemos la pregunta: ¿qué cantidad buscamos y en qué unidad? Elegimos los datos que ayudan a encontrarla. El precio o el color de una cinta no cambian cuánto mide. Si hay varios cortes, necesitamos saber cuántos y de qué longitud.','Una cinta de 2 m cuesta $40. Cortamos 3 trozos de 25 cm. Para saber cuántos cm quedan usamos 2 m, 3 cortes y 25 cm; el precio no interviene.',['Buscamos una longitud restante, en centímetros.','Anotamos longitud inicial, cantidad de cortes y longitud de cada corte. Dejamos fuera el precio.'],'La pregunta pide cuánto queda de cinta, no cuánto cuesta.',[act(f'Una cinta de {f(m)} m cuesta ${price}. Cortás {n} trozos de {c} cm. Para saber cuántos centímetros quedan, ¿qué datos necesitás?',f'{f(m)} m, {n} cortes y {c} cm',f'Buscamos la longitud restante. Usamos {f(m)} m al inicio y {n} cortes de {c} cm. El precio no cambia la longitud.',[f'${price} y {n} cortes',f'Solo {c} cm'],datos(f'Cinta: {f(m)} m',f'Cortes: {n} de {c} cm',f'Precio: ${price}')) for m,n,c,price in cuts],datos('Cinta: 2 m','Cortes: 3 de 25 cm','Precio: $40'))
unit('prof_prob_plan_cortes',t,'prof_prob_datos','Ordenar el plan antes de hacer las cuentas','Para varios cortes, primero expresamos toda la cinta en centímetros. Después multiplicamos la cantidad de cortes por lo que mide cada uno. Finalmente restamos esa longitud usada de la inicial. Escribir el plan permite saber para qué sirve cada cuenta.','Para una cinta de 2 m y tres cortes de 25 cm: convertir 2 m a cm, calcular tres cortes y restar lo usado.',['Primero: 2 × 100 = 200 cm. Después: 3 × 25 = 75 cm usados.','Finalmente: 200 − 75 = 125 cm. Comprobamos: 75 + 125 = 200.'],'El último paso debe dar la longitud que queda, después de todos los cortes.',[act(f'Tenés {f(m)} m de cinta y hacés {n} cortes de {c} cm. Querés saber cuánto queda en cm. ¿Qué plan sirve?', 'Convertir → calcular todos los cortes → restar',f'Pasamos {f(m)} m a cm. Calculamos {n} × {c} para reunir todos los cortes. Restamos lo usado de la cinta inicial.',['Sumar metros y centímetros → restar un corte','Restar un corte → multiplicar lo que queda'],datos(f'Cinta: {f(m)} m',f'Cortes: {n} de {c} cm','Buscamos: centímetros restantes')) for m,n,c,price in cuts],datos('Cinta: 2 m','Cortes: 3 de 25 cm','Buscamos: centímetros restantes'))
unit('prof_prob_cortes',t,'prof_prob_plan_cortes','Resolver y comprobar varios cortes','Ahora usamos el plan completo: convertimos, calculamos lo usado en todos los cortes y restamos. Para comprobar, sumamos lo usado y lo que queda: debe recuperar la cinta inicial. La respuesta lleva la unidad pedida.','De 2 m cortamos tres trozos de 25 cm. Quedan 125 cm de cinta.',['2 m = 200 cm. Los tres cortes usan 3 × 25 = 75 cm.','200 − 75 = 125 cm. Comprobación: 75 + 125 = 200 cm.'],'Calculá cuánto usan todos los cortes antes de restar.',[act(f'Una cinta mide {f(m)} m. Cortás {n} trozos de {c} cm. ¿Cuántos centímetros quedan?',f(D(m)*100-n*c),f'Inicial: {f(m)} × 100 = {f(D(m)*100)} cm.\nUsado: {n} × {c} = {n*c} cm.\nQueda: {f(D(m)*100)} − {n*c} = {f(D(m)*100-n*c)} cm.\nComprobamos: {n*c} + {f(D(m)*100-n*c)} = {f(D(m)*100)} cm.',[f(D(m)*100-c),f(D(m)*100+n*c)],datos(f'Cinta: {f(m)} m',f'Cortes: {n} de {c} cm','Buscamos: centímetros restantes')) for m,n,c,price in cuts],datos('Cinta: 2 m','Cortes: 3 de 25 cm','Buscamos: centímetros restantes'))
t='si_me_la_masa_capacidad_tiempo';drinks=[('1.4',250),('1.7',200),('2.3',300),('1.1',300),('2.6',400),('1.8',250)]
unit('prof_prob_vasos',t,'prof_med_cap_problema','Llenar solo los vasos que alcanzan','Cuando la división no es exacta, distinguimos vasos completos y líquido restante. Convertimos litros a mililitros y buscamos cuántos vasos enteros podemos llenar. Si el siguiente necesita más líquido del que queda, no lo contamos como completo.','Con 1,4 L y vasos de 250 mL se llenan 5 vasos: usan 1250 mL. El sexto necesitaría 1500 mL, más de lo disponible.',['1,4 L = 1400 mL. Cinco vasos usan 5 × 250 = 1250 mL.','Seis vasos usarían 1500 mL: no alcanza. Podemos llenar cinco completos.'],'Probá cuántos vasos enteros alcanzan; el siguiente no debe superar lo disponible.',[act(f'Tenés {f(l)} L de jugo y vasos de {c} mL. ¿Cuántos vasos completos podés llenar?',int(D(l)*1000)//c,f'{f(l)} L = {f(D(l)*1000)} mL.\n{int(D(l)*1000)//c} vasos usan {(int(D(l)*1000)//c)*c} mL. El siguiente llevaría {(int(D(l)*1000)//c+1)*c} mL: no alcanza.',[int(D(l)*1000)//c+1,int(D(l)*1000)//c-1],datos(f'Bebida: {f(l)} L',f'Cada vaso: {c} mL','Buscamos: vasos completos')) for l,c in drinks],datos('Bebida: 1,4 L','Cada vaso: 250 mL','Buscamos: vasos completos'))
unit('prof_prob_sobra',t,'prof_prob_vasos','Conservar el líquido que sobra','Después de contar los vasos completos, calculamos cuánto líquido usaron y lo restamos del total. El resto se expresa en mililitros, no en vasos. Debe ser menor que la capacidad de un vaso: si alcanzara para otro, todavía podríamos llenarlo.','Con 1400 mL llenamos cinco vasos de 250 mL y quedan 150 mL.',['Cinco vasos usan 5 × 250 = 1250 mL.','1400 − 1250 = 150 mL. Es menos que 250 mL y 1250 + 150 = 1400.'],'Restá el líquido usado en todos los vasos completos; conservá la unidad mL.',[act(f'Tenés {f(l)} L de jugo. Llenás todos los vasos completos posibles de {c} mL. ¿Cuántos mililitros sobran?',int(D(l)*1000)%c,f'{f(l)} L = {f(D(l)*1000)} mL.\nCaben {int(D(l)*1000)//c} vasos: usan {(int(D(l)*1000)//c)*c} mL.\nResto: {f(D(l)*1000)} − {(int(D(l)*1000)//c)*c} = {int(D(l)*1000)%c} mL, menos que un vaso.',[int(D(l)*1000)//c,c],datos(f'Bebida: {f(l)} L',f'Cada vaso: {c} mL','Buscamos: mililitros sobrantes')) for l,c in drinks],datos('Bebida: 1,4 L','Cada vaso: 250 mL','Buscamos: mililitros sobrantes'))
masses=[('2',3,250),('1.5',4,200),('3',5,400),('2.5',6,300),('1.2',3,150),('4',7,500)]
unit('prof_prob_porciones',t,'prof_med_masa_problema','Preparar varias porciones y guardar el resto','Para preparar porciones iguales, convertimos la masa inicial a gramos. Multiplicamos la cantidad de porciones por los gramos de cada una y restamos lo usado. Comprobamos que el resto más todas las porciones recuperen la masa inicial.','Con 2 kg de harina preparamos tres porciones de 250 g. Usamos 750 g y quedan 1250 g.',['2 kg = 2000 g. Tres porciones usan 3 × 250 = 750 g.','2000 − 750 = 1250 g. Comprobamos: 750 + 1250 = 2000 g.'],'Multiplicá todas las porciones antes de quitar lo usado.',[act(f'Tenés {f(kg)} kg de harina y preparás {n} porciones de {g} g. ¿Cuántos gramos quedan?',f(D(kg)*1000-n*g),f'Inicial: {f(kg)} kg = {f(D(kg)*1000)} g.\nUsado: {n} × {g} = {n*g} g.\nQueda: {f(D(kg)*1000)} − {n*g} = {f(D(kg)*1000-n*g)} g.',[f(D(kg)*1000-g),f(D(kg)*1000+n*g)],datos(f'Harina: {f(kg)} kg',f'Porciones: {n} de {g} g','Buscamos: gramos restantes')) for kg,n,g in masses],datos('Harina: 2 kg','Porciones: 3 de 250 g','Buscamos: gramos restantes'))
t='perimetros_simples';frames=[('2',50,3),('1.5',40,2),('3',75,2),('2.5',50,4),('1.2',30,3),('4',50,2)]
unit('prof_prob_plan_per',t,'mat_per_circunferencia','Preparar un plan para rodear varias veces','Si un rectángulo tiene lados en metros y centímetros, primero elegimos una sola unidad. Después sumamos sus cuatro lados para una vuelta. Recién entonces multiplicamos por la cantidad de vueltas. La pregunta indica en qué unidad responder.','Un marco de 2 m por 50 cm lleva tres vueltas de cinta. Podemos convertir todo a cm, hallar una vuelta y multiplicarla por tres.',['En cm, los lados son 200 y 50. Una vuelta: 200 + 50 + 200 + 50 = 500 cm.','Tres vueltas: 500 × 3 = 1500 cm. Si piden metros: 1500 ÷ 100 = 15 m.'],'Primero igualá las unidades; una vuelta incluye los cuatro lados.',[act(f'Un marco mide {f(m)} m por {cm} cm y necesita {n} vueltas de cinta. ¿Qué plan calcula la longitud total?', 'Igualar unidades → sumar cuatro lados → multiplicar vueltas',f'Convertimos los lados a una misma unidad, sumamos una vuelta completa y multiplicamos por {n}.',['Sumar los dos números → multiplicar vueltas','Multiplicar largo por ancho → sumar vueltas'],rectangle(m,cm,f'{n} vueltas de cinta')) for m,cm,n in frames],rectangle('2',50,'3 vueltas de cinta'))
unit('prof_prob_vueltas',t,'prof_prob_plan_per','Calcular la cinta para varias vueltas','Resolvemos el plan y cuidamos la unidad final. Una vuelta es el perímetro del marco; varias vueltas repiten esa longitud. Podemos calcular en centímetros y, si piden metros, dividir el total por 100 al final.','El marco de 2 m por 50 cm necesita 15 m de cinta para tres vueltas.',['2 m = 200 cm. Perímetro: 200 + 50 + 200 + 50 = 500 cm.','Tres vueltas: 500 × 3 = 1500 cm. En metros: 1500 ÷ 100 = 15 m.'],'Anotá por separado una vuelta y todas las vueltas; revisá la unidad pedida.',[act(f'Un marco mide {f(m)} m de largo y {cm} cm de ancho. Lo rodeás con {n} vueltas completas de cinta. ¿Cuántos metros de cinta necesitás?',f((D(m)*100+cm)*2*n/100),f'Largo: {f(m)} m = {f(D(m)*100)} cm.\nUna vuelta: 2 × ({f(D(m)*100)} + {cm}) = {f((D(m)*100+cm)*2)} cm.\n{n} vueltas: {f((D(m)*100+cm)*2*n)} cm = {f((D(m)*100+cm)*2*n/100)} m.',[f((D(m)*100+cm)*2/100),f((D(m)*100+cm)*n/100)],rectangle(m,cm,f'{n} vueltas; respuesta en metros')) for m,cm,n in frames],rectangle('2',50,'3 vueltas; respuesta en metros'))
rolls=[(4,3,5),(5,3,4),(6,4,3),(3,2,4),(7,3,5),(8,3,4)]
unit('prof_prob_rollos',t,'prof_prob_vueltas','Comprar rollos completos que alcancen','Para una vuelta de alambre calculamos el perímetro del terreno. Dividimos por la longitud de cada rollo. Si queda una parte por cubrir, necesitamos un rollo más; si la división es exacta, no agregamos otro. Aquí se puede unir el alambre de los rollos.','Un terreno de 4 m por 3 m tiene 14 m de borde. Con rollos de 5 m, dos dan 10 m y no alcanzan: compramos tres.',['Perímetro: 4 + 3 + 4 + 3 = 14 m. Dos rollos dan 10 m, faltan 4 m.','Tres rollos dan 15 m: alcanzan y sobra 1 m. No necesitamos un cuarto.'],'Comprobá que los rollos comprados alcancen y que uno menos no alcance.',[act(f'Un terreno rectangular mide {b} m por {h} m. Querés una vuelta de alambre y podés unir los rollos. Cada rollo tiene {r} m y se vende entero. ¿Cuál es la menor cantidad de rollos que alcanza?',(2*(b+h)+r-1)//r,f'Perímetro: 2 × ({b} + {h}) = {2*(b+h)} m.\n{(2*(b+h)+r-1)//r} rollos dan {((2*(b+h)+r-1)//r)*r} m: alcanza.\nUno menos da {(((2*(b+h)+r-1)//r)-1)*r} m: no alcanza.',[(2*(b+h)+r-1)//r-1,(2*(b+h)+r-1)//r+1],rectangle(str(b),h*100,f'Una vuelta; rollos de {r} m',True)) for b,h,r in rolls],rectangle('4',300,'Una vuelta; rollos de 5 m',True))
prices=[(3,2,2,4),(4,3,1,5),(5,2,3,2),(6,4,2,3),(3,3,2,5),(7,2,1,6)]
unit('prof_prob_costo',t,'prof_prob_rollos','Calcular cuánto cuesta la cinta','Cuando la cinta se vende por metro, primero calculamos los metros necesarios para todas las vueltas. Después multiplicamos esa longitud por el precio de un metro. No multiplicamos el precio por la superficie: compramos cinta para el borde.','Un marco de 3 m por 2 m necesita 20 m para dos vueltas. A $4 por metro, la cinta cuesta $80.',['Una vuelta: 3 + 2 + 3 + 2 = 10 m. Dos vueltas: 10 × 2 = 20 m.','Costo: 20 × 4 = $80. Respondemos dinero, no metros.'],'Calculá los metros de todas las vueltas antes de usar el precio por metro.',[act(f'Un marco rectangular mide {b} m por {h} m. Lleva {n} vuelta(s) de cinta. La cinta se vende por metro a ${price}. ¿Cuántos pesos cuesta la cinta necesaria?',2*(b+h)*n*price,f'Una vuelta: 2 × ({b} + {h}) = {2*(b+h)} m.\nTodas las vueltas: {2*(b+h)} × {n} = {2*(b+h)*n} m.\nCosto: {2*(b+h)*n} × {price} = ${2*(b+h)*n*price}.',[2*(b+h)*n,b*h*n*price],rectangle(str(b),h*100,f'{n} vuelta(s); ${price} por metro',True)) for b,h,n,price in prices],rectangle('3',200,'2 vueltas; $4 por metro',True))
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R15: problemas por etapas.';end='// FIN R15'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst PROBLEMAS_R15 = '+json.dumps(U,ensure_ascii=False,indent=2)+""";
for (const unidad of PROBLEMAS_R15) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === unidad.despues_de);
 if (indice < 0) throw new Error('Falta el paso anterior de ' + unidad.id);
 UNIDADES_BASES.splice(indice + 1, 0, unidad);
}
"""+end+'\n\n';i=min(s.index(m) for m in ['// R16: lectura con evidencia.','// R17: idea principal y resumen.','// R18: escritura guiada.','export const TEMAS_BASES'] if m in s);p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
